import pathlib,json,hashlib,subprocess,datetime
root=pathlib.Path('/home/julcapp/soft-ice-worktrees/display-product-v1/backend/src/modules/bot_core')
data=json.loads("[{\"name\": \"BotActionRouter.js\", \"before\": \"397162f3561d4b1755e88887babf7a02052c65eef342bc40242bde52d262d0cf\", \"content\": \"const { parseGiftAction } = require('./BotGiftActionService');\\n\\nclass BotActionRouter {\\n  constructor({ customerExperienceService, giftActionService = null, onboardingPolicy = null } = {}) {\\n    this.customerExperienceService = customerExperienceService;\\n    this.giftActionService = giftActionService;\\n    this.onboardingPolicy = onboardingPolicy;\\n  }\\n\\n  async route({ action, customerId, channel, context = {} }) {\\n    const giftAction = parseGiftAction(action);\\n    if (giftAction) {\\n      if (!this.giftActionService) return featureUnavailableView();\\n      return this.giftActionService.acceptGift({\\n        customerId,\\n        giftId: giftAction.giftId,\\n        channel,\\n        context,\\n      });\\n    }\\n\\n    switch (action) {\\n      case 'club':\\n        return this.customerExperienceService.buildClubView({ customerId, channel, context });\\n      case 'referral':\\n        return this.customerExperienceService.buildReferralView({ customerId, channel, context });\\n      case 'gifts':\\n        if (!this.giftActionService) return featureUnavailableView();\\n        return this.giftActionService.listGifts({ customerId, channel, context });\\n      case 'main_menu':\\n      case 'back':\\n      case 'menu':\\n        return this.customerExperienceService.buildMainMenuView({ customerId, channel, context });\\n      case 'order':\\n      case 'open_mini_app':\\n        return this.customerExperienceService.buildMiniAppView({ customerId, channel, context });\\n      case 'help': {\\n        const app = await this.customerExperienceService.buildMiniAppView({ customerId, channel, context });\\n        return { title: 'Помощь', text: 'Заказы, оплату и код получения смотрите в приложении. Если заказ уже оплачен, повторно платить не нужно: откройте кабинет и проверьте его статус. Подарки и приглашения доступны отдельными кнопками бота.',\\n          actions: [...(app.actions || []), { type: 'action', label: '← Главное меню', action: 'menu' }] };\\n      }\\n      case 'locations':\\n        return { title: 'Где купить', text: 'Список адресов аппаратов в боте пока не подключён. Не оформляйте заказ, если не уверены, где находится выбранный аппарат.',\\n          actions: [{ type: 'action', label: '← Главное меню', action: 'menu' }] };\\n      default:\\n        return {\\n          title: 'У Тимоши',\\n          text: 'Не удалось распознать действие. Откройте главное меню.',\\n          actions: [{ type: 'action', label: '← Главное меню', action: 'menu' }],\\n        };\\n    }\\n  }\\n}\\n\\nfunction featureUnavailableView() {\\n  return {\\n    title: 'Подарки временно недоступны',\\n    text: 'Откройте Mini App или повторите попытку позже.',\\n    actions: [{ type: 'action', label: '← Главное меню', action: 'menu' }],\\n  };\\n}\\n\\nmodule.exports = { BotActionRouter };\\n\"}, {\"name\": \"BotClubView.js\", \"before\": \"0cc2169702f866b0280532815affa5fa0bdc9e189a333102eaddb63c6eee2af6\", \"content\": \"function buildClubSummary({ customerName = null, moneyBalanceRub = 0, bonusBalance = 0, welcomeBonus = null, referralSummary = null, miniAppUrl = null } = {}) {\\n  const lines = [];\\n  if (customerName) lines.push(`${customerName}, ваш Клуб Тимоши 🍦`);\\n  else lines.push('Ваш Клуб Тимоши 🍦');\\n  lines.push(`Клубный счёт: ${Number(moneyBalanceRub || 0).toFixed(2)} ₽`);\\n  lines.push(`Бонусы: ${Number(bonusBalance || 0)}`);\\n  if (welcomeBonus?.status === 'active') {\\n    lines.push(`Приветственный бонус: ${Number(welcomeBonus.amountRemaining || 0)}`);\\n    if (welcomeBonus.expiresAt) lines.push(`Действует до: ${formatDate(welcomeBonus.expiresAt)}`);\\n  }\\n  if (referralSummary) {\\n    lines.push(`Приглашено друзей: ${Number(referralSummary.invited || 0)}`);\\n    lines.push(`Выполнили условие: ${Number((referralSummary.firstPurchase || 0) + (referralSummary.qualifiedTopup || 0))}`);\\n  }\\n\\n  return {\\n    title: '🎁 Мой клуб',\\n    text: lines.join('\\\\n'),\\n    actions: [\\n      { type: 'action', action: 'referral', label: '👥 Пригласить друга' },\\n      miniAppUrl ? { type: 'open_mini_app', label: '📱 Открыть личный кабинет', url: miniAppUrl } : null,\\n      { type: 'action', action: 'menu', label: '← Назад' },\\n    ].filter(Boolean),\\n  };\\n}\\n\\nfunction buildReferralRewardNotification({ amountBonus = null, miniAppUrl = null } = {}) {\\n  return {\\n    kind: 'referral_reward',\\n    title: '🎁 Вам начислен бонус!',\\n    text: amountBonus == null\\n      ? 'Приглашённый вами друг выполнил условия программы. Награда уже зачислена.'\\n      : `Приглашённый вами друг выполнил условия программы. Вам начислено ${Number(amountBonus)} бонусов.`,\\n    actions: [\\n      { type: 'action', action: 'referral', label: 'Посмотреть приглашения' },\\n      miniAppUrl ? { type: 'open_mini_app', label: 'Открыть Клуб Тимоши', url: miniAppUrl } : null,\\n    ].filter(Boolean),\\n  };\\n}\\n\\nfunction buildReferralQualifiedNotification() {\\n  return {\\n    kind: 'referral_qualified',\\n    title: '🍦 Приглашение выполнено',\\n    text: 'Ваш друг выполнил условие реферальной программы. Мы оформляем предусмотренное вознаграждение.',\\n  };\\n}\\n\\nfunction formatDate(value) {\\n  const date = value instanceof Date ? value : new Date(value);\\n  if (Number.isNaN(date.getTime())) return String(value);\\n  return new Intl.DateTimeFormat('ru-RU', { day: '2-digit', month: '2-digit', year: 'numeric' }).format(date);\\n}\\n\\nmodule.exports = { buildClubSummary, buildReferralRewardNotification, buildReferralQualifiedNotification };\\n\"}, {\"name\": \"TelegramRenderer.js\", \"before\": \"514d6d453c30c65f0a9a0c7132c784fcceae9bcd3d00ed30ee92c9ee48deda76\", \"content\": \"const { TransportRenderer } = require('./TransportRenderer');\\n\\nclass TelegramRenderer extends TransportRenderer {\\n  constructor({ features = {}, miniAppEntryPolicy = action => action } = {}) {\\n    super();\\n    this.miniAppEntryPolicy = miniAppEntryPolicy;\\n    this.features = {\\n      disabledButtons: features.disabledButtons === true,\\n    };\\n  }\\n\\n  renderView(view, { chatType = null, externalUserId = null } = {}) {\\n    const base = super.renderView(view);\\n    const entryContext = { chatType, externalUserId };\\n    base.actions = this.miniAppEntryPolicy.mapMenu?.(base.actions, entryContext) || base.actions;\\n    base.actions = base.actions.map(action => this.miniAppEntryPolicy(action, entryContext));\\n    const telegram = view?.channelOptions?.telegram || {};\\n    const requestContact = chatType === 'private' && base.actions.some((action) => action.type === 'request_contact');\\n    return {\\n      text: base.text,\\n      reply_markup: requestContact ? {\\n        keyboard: base.actions.filter((action) => action.type === 'request_contact' || action.type === 'open_mini_app')\\n          .map((action) => [action.type === 'request_contact' ? { text: action.label, request_contact: true }\\n            : toTelegramButton(action, this.features, { chatType })]),\\n        resize_keyboard: true, one_time_keyboard: true,\\n      } : {\\n        inline_keyboard: base.actions\\n          .map((action) => [toTelegramButton(action, this.features, { chatType })])\\n          .filter((row) => row[0]),\\n      },\\n      rich_message: telegram.richMessage || null,\\n      delivery: telegram.delivery || null,\\n    };\\n  }\\n}\\n\\nfunction toTelegramButton(action, features = {}, { chatType = null } = {}) {\\n  if (!action) return null;\\n  const disabled = action?.channelOptions?.telegram?.disabled === true;\\n  if (disabled) {\\n    return features.disabledButtons ? { text: action.label, disabled: {} } : null;\\n  }\\n  if (action.type === 'open_mini_app' && action.url && chatType === 'private') {\\n    const url = new URL(action.url);\\n    if (url.protocol !== 'https:') throw new Error('Telegram Mini App requires HTTPS.');\\n    return { text: action.label, web_app: { url: action.url } };\\n  }\\n  if (['open_url', 'open_mini_app', 'share', 'qr'].includes(action.type) && action.url) {\\n    return { text: action.label, url: action.url };\\n  }\\n  if (action.type === 'copy' && action.value) {\\n    return { text: action.label, callback_data: `copy:${action.value}`.slice(0, 64) };\\n  }\\n  if (action.action) return { text: action.label, callback_data: `action:${action.action}` };\\n  return null;\\n}\\n\\nmodule.exports = { TelegramRenderer, toTelegramButton };\\n\"}, {\"name\": \"TestMiniAppEntryPolicy.js\", \"before\": \"e91f8edd6214d39bd0b55c1e77b2a4e59d329e8e64be5dddd0804a6815984475\", \"content\": \"const fs = require('node:fs');\\n\\nfunction createTestMiniAppEntryPolicy({ token, env = process.env, readConfig = readTestConfig } = {}) {\\n  const entry = (action, { chatType, externalUserId } = {}) => {\\n    if (env.NODE_ENV === 'production' || chatType !== 'private' || !externalUserId || action.type !== 'open_mini_app') return action;\\n    let config;\\n    try { config = readConfig(); } catch { return action; }\\n    if (!token || token !== config.token || !token.startsWith('572898079:') || !config.allowedUserIds.has(String(externalUserId))) return action;\\n    let previous;\\n    try { previous = new URL(action.url); } catch { return action; }\\n    if (previous.protocol !== 'https:' || !['app.utimoshi.ru', 'miniapp.utimoshi.ru'].includes(previous.hostname)) return action;\\n    // Route the TEST buyer to the shared server-backed account, preserving context.\\n    const url = new URL('https://bot-test.utimoshi.ru/miniapp/');\\n    url.search = previous.search;\\n    return { ...action, url: url.href };\\n  };\\n  entry.mapMenu = (actions, { chatType, externalUserId } = {}) => {\\n    if (env.NODE_ENV === 'production' || chatType !== 'private' || !externalUserId) return actions;\\n    let config;\\n    try { config = readConfig(); } catch { return actions; }\\n    if (!token || token !== config.token || !token.startsWith('572898079:') || !config.allowedUserIds.has(String(externalUserId))) return actions;\\n    const expected = ['club', 'gifts', 'referral', 'order', 'locations', 'help'];\\n    if (!expected.every(name => actions.some(action => action.action === name))) return actions;\\n    return actions.filter(action => action.type === 'open_mini_app' || ['gifts', 'referral', 'help'].includes(action.action))\\n      .map(action => action.type === 'open_mini_app' ? { ...action, label: '📱 Кабинет · заказы и получение' } : action);\\n  };\\n  return entry;\\n}\\n\\nfunction readTestConfig() {\\n  const values = {};\\n  for (const line of fs.readFileSync('/etc/softice/miniapp-test-auth.env', 'utf8').split(/\\\\r?\\\\n/)) {\\n    const match = line.match(/^(TELEGRAM_TEST_BOT_TOKEN|TELEGRAM_TEST_ALLOWED_USER_IDS)=(.*)$/);\\n    if (match) values[match[1]] = match[2].trim().replace(/^(['\\\"])(.*)\\\\1$/, '$2');\\n  }\\n  return { token: values.TELEGRAM_TEST_BOT_TOKEN,\\n    allowedUserIds: new Set(String(values.TELEGRAM_TEST_ALLOWED_USER_IDS || '').split(',').map(x => x.trim()).filter(Boolean)) };\\n}\\n\\nmodule.exports = { createTestMiniAppEntryPolicy };\\n\"}]\n")
